var t=`1420-cassava-pudding`;var i=`world-1420`;var e=`SB`;var o=`oceania`;var s=6;var u=88;var c={en:`Cassava Pudding`,ua:`Пудинг із маніоку`};var l={en:`A Solomon Islands-style moist cassava-and-coconut pudding baked until firm.`,ua:`Вологий маніоково-кокосовий пудинг за мотивами кухні Соломонових Островів, запечений до щільної текстури.`};var d=[{en:`Preheat oven to 180°C and lightly oil a medium baking dish.`,ua:`Розігрійте духовку до 180°C і злегка змастіть середню форму для запікання.`,t:[`preheating`],m:4,i:[[`coconut-oil`,15,`ml`]]},{en:`Combine cassava flour, coconut sugar and salt. Stir in desiccated coconut.`,ua:`Змішайте маніокове борошно, кокосовий цукор і сіль. Додайте кокосову стружку.`,t:[`mixing`],m:7,i:[[`cassava-flour`,260,`g`],[`coconut-sugar`,135,`g`],[`sea-salt`,3,`g`],[`desiccated-coconut`,110,`g`]]},{en:`Mix in coconut milk and water until smooth and pourable but fairly thick.`,ua:`Умішайте кокосове молоко й воду до гладкої, досить густої, але текучої маси.`,t:[`mixing`],m:7,i:[[`coconut-milk`,420,`ml`],[`water`,100,`ml`]]},{en:`Pour into the dish and bake 45–55 minutes until the centre is no longer runny and the top is golden.`,ua:`Перелийте у форму й випікайте 45–55 хвилин, доки середина перестане бути рідкою, а верх стане золотистим.`,t:[`baking`],m:50,i:[]},{en:`Cool at least 20 minutes to set before cutting into squares.`,ua:`Дайте охолонути не менше 20 хвилин, щоб маса схопилася, тоді наріжте квадратами.`,t:[`garnishing`],m:20,i:[]}];var g={slug:t,id:i,country:`SB`,region:o,servings:6,minutes:88,title:c,text:l,steps:d};export{e as country,g as default,i as id,u as minutes,o as region,s as servings,t as slug,d as steps,l as text,c as title};